pm.test('Status 201 Created', function () {
    pm.response.to.have.status(201);
});

const struk = pm.response.json().data;

pm.test('AB-1 subtotal = 101.800', function () {
    pm.expect(struk.subtotal).to.eql(101800);
});

pm.test('AB-2 diskon grosir 5% pada baris kuantitas 12', function () {
    pm.expect(struk.diskon_grosir).to.eql(2040);
});

pm.test('AB-3 diskon member 3% dari subtotal setelah diskon grosir', function () {
    pm.expect(struk.diskon_member).to.eql(2993);
});

pm.test('AB-5 PPN 11% dari DPP, dibulatkan', function () {
    pm.expect(struk.dpp).to.eql(96767);
    pm.expect(struk.ppn).to.eql(10644);
});

pm.test('AB-6 total dibulatkan ke atas kelipatan 100', function () {
    pm.expect(struk.total_bayar % 100).to.eql(0);
    pm.expect(struk.total_bayar).to.eql(107500);
});

pm.test('AB-7 kembalian = dibayar - total bayar', function () {
    pm.expect(struk.kembalian).to.eql(
        struk.dibayar - struk.total_bayar
    );
});

pm.test('Nomor struk berformat POS-YYYYMMDD-NNNN', function () {
    pm.expect(struk.nomor).to.match(/^POS-\d{8}-\d{4}$/);
});

pm.collectionVariables.set('nomor_struk', struk.nomor);

