});

const data = pm.response.json().data;

pm.test('Pemasok utama berada di urutan pertama', function () {
    pm.expect(data.pemasok[0].utama).to.eql(true);
});

pm.test('AB-13 margin = harga jual - harga beli', function () {
    const p = data.pemasok[0];

    pm.expect(p.margin).to.eql(data.harga - p.harga_beli);
    pm.expect(p.margin).to.eql(3600);
});

pm.test('Margin berupa bilangan bulat rupiah', function () {
    pm.expect(data.pemasok[0].margin % 1).to.eql(0);
});

pm.test('AB-13 kasir ditolak', function () {
    pm.response.to.have.status(403);

    pm.expect(pm.response.json().kesalahan)
        .to.eql('peran_tidak_berwenang');
});

pm.test('Harga beli tidak ikut terkirim pada response penolakan', function () {
    pm.expect(pm.response.text()).to.not.include('harga_beli');
});

pm.test('Status 200 OK', function () {
    pm.response.to.have.status(200);
});

const isi = pm.response.json();

pm.test('Seluruh kategori tampil, termasuk yang tanpa penjualan', function () {
    pm.expect(isi.data).to.have.lengthOf(4);
});

pm.test('Kategori tanpa penjualan bernilai nol, bukan null', function () {
    const kosong = isi.data.find(function (d) {
        return d.kode === 'alat_tulis';
    });

    pm.expect(kosong.kuantitas).to.eql(0);
    pm.expect(kosong.pendapatan).to.eql(0);
});

pm.test('meta.total_pendapatan sama dengan jumlah seluruh baris', function () {
    const jumlah = isi.data.reduce(function (a, d) {
        return a + d.pendapatan;
    }, 0);

    pm.expect(isi.meta.total_pendapatan).to.eql(jumlah);
    pm.expect(jumlah).to.eql(228760);
});
